def guardar_valores_previos(apps, schema_editor):
    Credencial = apps.get_model('policies', 'AseguradoraCredencial')
    for nombre, valores in VALORES_PREVIOS.items():
        for credencial in Credencial.objects.filter(aseguradora__name=nombre):
            credencial.parametros = {**valores, **(credencial.parametros or {})}
            credencial.save(update_fields=['parametros'])


